// "DUKUN vs DEMIT 3D" -- the GPU-rendered adaptation of the Halloween horror featurette.
// Every asset is still generated by code: the world is built from g3d primitives (real
// GPU lighting, shadows, fog and depth of field), the 2D layers from rmtn/draw.hpp, and
// the soundtrack from synth sine sums plus code-generated rain/wind/screech WAVs.
//
//   raymotion_halloween3d list
//   raymotion_halloween3d preview dukun-vs-demit-3d
//   raymotion_halloween3d render  dukun-vs-demit-3d     -> out/dukun-vs-demit-3d.mp4
//   raymotion_halloween3d still   dukun-vs-demit-3d --at 900
#include "rmtn/raymotion.hpp"

#include <algorithm>
#include <cmath>
#include <filesystem>
#include <memory>
#include <string>
#include <vector>

using namespace rmtn;

namespace {

using V2 = Vector2;
using V3 = Vector3;

constexpr float W = 1920, H = 1080;
constexpr int FPS = 30;
constexpr int TR = 24;                    // transition overlap between shots, frames
constexpr unsigned long long SEED = 19741101;
const std::string AUDIO_DIR = "out/hw-audio-v1";   // shared with the 2D cut

const Color NIGHT_TOP  = mkColor(0x04050e);
const Color NIGHT_BOT  = mkColor(0x150a1e);
const Color BONE       = mkColor(0xe8e2d0);
const Color DEMIT_RED  = mkColor(0xff2b18);
const Color FLAME      = mkColor(0xffb347);
const Color FOG_COL    = mkColor(0x0b0818);

// ================================================================== shared 2D helpers
float flashAt(int t, unsigned long long salt) {
    float f = 0;
    for (int k = 0; k < 20; k++) {
        double ef = 8 + k * 46 + rrange(SEED, salt * 31 + k, 0, 30);
        double d = (double)t - ef;
        if (d >= 0 && d < 6) f = std::max(f, (float)std::exp(-d * 1.4));
    }
    return f;
}

void rain(const Ctx& cx, int t, float intensity, float wind = 90.f) {
    if (intensity <= 0.01f) return;
    for (int i = 0; i < 190; i++) {
        V2 p = rvec2(SEED, 500, i);
        float speed = 900 + 500 * p.x;
        float x = (float)std::fmod(p.x * (W + 200) + t * wind, W + 200) - 100;
        float y = (float)std::fmod(p.y * (H + 200) + t * speed, H + 200) - 100;
        float len = 16 + 12 * p.y;
        dr::strokeSeg(cx, { x, y }, { x - wind * 0.03f * len, y + len }, 1.8f,
                      withAlpha(mkColor(0xaab4d8), 0.15f * intensity));
    }
}

void fog2d(const Ctx& cx, int t, float y0, unsigned long long salt, float alpha) {
    for (int i = 0; i < 8; i++) {
        float x = (float)std::fmod((float)rrange(SEED, salt + i, 0, W) + t * (6 + 5 * i), W + 500) - 250;
        float y = y0 + 16.f * (float)std::sin(t * 0.05 + i);
        dr::blob(cx, { x, y }, 110 + 30.f * (i % 3), 12, 3, i * 57.f + t, withAlpha(mkColor(0x9a8fc0), alpha));
    }
}

// stars + blood moon (the 3D world renders on top of this backdrop)
void nightBackdrop(const Ctx& cx, int t, float flash, float dawn = 0) {
    Color top = mixC(mixC(NIGHT_TOP, mkColor(0x3a4668), flash * 0.7), mkColor(0x2c4a7a), dawn);
    Color bot = mixC(mixC(NIGHT_BOT, mkColor(0x54425e), flash * 0.5), mkColor(0xff9a52), dawn);
    dr::rectGrad4(cx, 0, 0, W, H, top, top, bot, bot);
    for (int i = 0; i < 130; i++) {
        V2 p = rvec2(SEED, 3, i);
        float tw = 0.5f + 0.5f * (float)std::sin(t * 0.13 + i * 1.71);
        dr::rect(cx, p.x * W, p.y * H * 0.6f, 2.6f, 2.6f,
                 withAlpha(mkColor(0xdfe8ff), (0.18f + 0.55f * tw) * (1 - flash) * (1 - dawn)));
    }
    V2 m{ W * 0.78f, H * 0.20f };
    for (int i = 5; i >= 1; i--) dr::circle(cx, m, 46.f + 22 * i, withAlpha(mkColor(0xd8402c), 0.03f * (1 - dawn)));
    dr::circle(cx, m, 46, mixC(mkColor(0xf0eaff), mkColor(0xff5030), 0.55f * (1 - dawn)));
    dr::circle(cx, { m.x - 13, m.y - 8 }, 9, withAlpha(mkColor(0x9a90c8), 0.5f * (1 - dawn)));
    dr::circle(cx, { m.x + 11, m.y + 12 }, 7, withAlpha(mkColor(0x9a90c8), 0.4f * (1 - dawn)));
}

void caption(const Ctx& cx, const std::string& s, float y, float a, float size);

float capA(double t, double in0, double in1, double out0, double out1) {
    return (float)interpolate(t, { in0, in1, out0, out1 }, { 0, 1, 1, 0 }, clamped());
}

// ------------------------------------------------------------------ typography department
// A real cinematic serif (Georgia on Windows), falling back to the bundled Inter.
Font serif(int style = 0) {                     // 0 regular, 1 bold, 2 italic
    static Font faces[3] = {
        [] {
            try { return fonts::load({ "georgia.ttf", "times.ttf", "Inter-Regular.ttf" }, 96); }
            catch (...) { return fonts::ui(false); }
        }(),
        [] {
            try { return fonts::load({ "georgiab.ttf", "timesbd.ttf", "Inter-Bold.ttf" }, 96); }
            catch (...) { return fonts::ui(true); }
        }(),
        [] {
            try { return fonts::load({ "georgiai.ttf", "timesi.ttf", "georgia.ttf", "Inter-Regular.ttf" }, 96); }
            catch (...) { return fonts::ui(false); }
        }(),
    };
    return faces[style];
}

// letter-tracked centred text: the title-card workhorse
void tracked(const Ctx& cx, const std::string& s, float centerX, float y, float size,
             float track, Color col, float a, int style = 1) {
    if (a <= 0.005f) return;
    Font f = serif(style);
    float total = -track;
    for (char ch : s) total += MeasureTextEx(f, std::string(1, ch).c_str(), size, 0).x + track;
    float x = centerX - total / 2;
    for (char ch : s) {
        float w = MeasureTextEx(f, std::string(1, ch).c_str(), size, 0).x;
        dr::text(f, cx, std::string(1, ch).c_str(), { x, y }, size, 0, withAlpha(col, a), 0.0, 0.0);
        x += w + track;
    }
}

// thin gold rule of `half` px each side of centerX
void rule(const Ctx& cx, float centerX, float y, float half, float a, float w = 2) {
    if (a <= 0.005f) return;
    dr::rect(cx, centerX - half, y, half * 2, w, withAlpha(mkColor(0xcf9a50), a));
    dr::star(cx, { centerX - half, y + w / 2 }, 5, 2, 4, 0, withAlpha(mkColor(0xcf9a50), a));
    dr::star(cx, { centerX + half, y + w / 2 }, 5, 2, 4, 0, withAlpha(mkColor(0xcf9a50), a));
}

// act card: tracked act label over a rule, serif title under it
void actCard(const Ctx& cx, const char* label, const char* title, float a) {
    if (a <= 0.005f) return;
    tracked(cx, label, W / 2, H * 0.40f, 26, 14, mkColor(0xcf9a50), a, 1);
    rule(cx, W / 2, H * 0.40f + 44, 120, a);
    tracked(cx, title, W / 2, H * 0.40f + 64, 52, 10, BONE, a, 1);
}

void caption(const Ctx& cx, const std::string& s, float y, float a, float size = 40) {
    if (a <= 0.005f) return;
    // soft shadow for legibility, then the serif line
    TextStyle st;
    st.font = serif(0);
    st.size = size;
    st.align = Align::Center;
    st.valign = Align::Center;
    st.color = { 0, 0, 0, (unsigned char)(160 * a) };
    dr::textBox(cx, s, { 120 + 2, y + 2, W - 240, size * 2.6f }, st);
    st.color = withAlpha(BONE, a);
    dr::textBox(cx, s, { 120, y, W - 240, size * 2.6f }, st);
}

void grainVignette(const Ctx& cx, int t) {
    dr::ring(cx, { W / 2, H / 2 }, H * 1.02f, H * 0.45f, mkColor(0, 55));
    dr::rect(cx, 0, 0, W, H * 0.055f, BLACK);
    dr::rect(cx, 0, H - H * 0.055f, W, H * 0.055f, BLACK);
    for (int i = 0; i < 300; i++) {
        V2 p = rvec2(SEED, 9000 + (t % 2) * 7, i);
        float v = (float)rnd01(SEED, 7000 + i + t * 131);
        dr::rect(cx, p.x * W, p.y * (H - H * 0.11f) + H * 0.055f, 2, 2,
                 v > 0.5f ? Color{ 255, 255, 255, 14 } : Color{ 0, 0, 0, 20 });
    }
}

// ================================================================== generated audio (shared with the 2D cut)
bool audioReady = false;

void ensureAudio() {
    if (audioReady) return;
    audioReady = true;
    std::error_code ec;
    std::filesystem::create_directories(AUDIO_DIR, ec);
    if (std::filesystem::exists(AUDIO_DIR + "/rain.wav") && std::filesystem::exists(AUDIO_DIR + "/wind.wav") &&
        std::filesystem::exists(AUDIO_DIR + "/screech.wav"))
        return;
    const int rate = 22050;
    if (!std::filesystem::exists(AUDIO_DIR + "/rain.wav")) {
        std::vector<float> s((size_t)rate * 20);
        double lp = 0;
        for (size_t i = 0; i < s.size(); i++) {
            double n = rnd01(1, i) * 2 - 1;
            lp += 0.28 * (n - lp);
            double pat = 0;
            if (rnd01(7, i / 700) < 0.002) pat = (rnd01(9, i) * 2 - 1) * std::exp(-(double)(i % 700) / 60);
            s[i] = (float)(0.30 * lp + 0.16 * pat);
        }
        writeWavMono(AUDIO_DIR + "/rain.wav", rate, s);
    }
    if (!std::filesystem::exists(AUDIO_DIR + "/wind.wav")) {
        std::vector<float> s((size_t)rate * 20);
        double lp1 = 0, lp2 = 0;
        for (size_t i = 0; i < s.size(); i++) {
            double n = rnd01(11, i) * 2 - 1;
            lp1 += 0.02 * (n - lp1);
            lp2 += 0.004 * (lp1 - lp2);
            double swell = 0.6 + 0.4 * std::sin(2 * PI * i / (rate * 7.3));
            s[i] = (float)(2.4 * lp2 * swell);
        }
        writeWavMono(AUDIO_DIR + "/wind.wav", rate, s);
    }
    if (!std::filesystem::exists(AUDIO_DIR + "/screech.wav")) {
        std::vector<float> s((size_t)(rate * 1.6));
        for (size_t i = 0; i < s.size(); i++) {
            double u = (double)i / s.size();
            double f = 1500 - 950 * u + 60 * std::sin(u * 50);
            double env = std::min(u / 0.06, 1.0) * std::exp(-2.2 * u);
            double v = std::sin(2 * PI * f * i / rate) * (0.6 + 0.4 * std::sin(2 * PI * 83 * i / rate));
            s[i] = (float)(0.5 * env * v + 0.10 * env * (rnd01(13, i) * 2 - 1));
        }
        writeWavMono(AUDIO_DIR + "/screech.wav", rate, s);
    }
}

// ================================================================== 3D world builders
g3d::Material matte(Color c) {
    g3d::Material m;
    m.color = c;
    m.roughness = 0.9f;
    return m;
}

g3d::Material glow(Color c, Color e) {
    g3d::Material m;
    m.color = c;
    m.emissive = e;
    m.roughness = 0.4f;
    return m;
}

// Night world base: hemisphere-ish environment, dark ground, linear fog.
void nightWorld(g3d::ScenePtr scene) {
    scene->environmentGenerator = g3d::studioEnvironment(mkColor(0x252c48), mkColor(0x12162a), mkColor(0x07070f), 3);
    scene->environmentIntensity = 0.55f;
    scene->fogColor = FOG_COL;
    scene->fogNear = 12;
    scene->fogFar = 58;
    scene->add(g3d::Geometry::plane(300, 300), matte(mkColor(0x0e0a1a)));
}

// nisan grave marker: slab + rounded cap
void grave3d(g3d::ScenePtr scene, V3 at, float s, float turnDeg) {
    g3d::Object3D* g = scene->add();
    g->position = at;
    g->rotation = { 0, turnDeg, 0 };
    g->scale = { s, s, s };
    g->add(g3d::Geometry::box(0.9f, 1.1f, 0.22f), matte(mkColor(0x231b33)))->position = { 0, 0.55f, 0 };
    g3d::Object3D* cap = g->add(g3d::Geometry::cylinder(0.45f, 0.22f, 24), matte(mkColor(0x28203c)));
    cap->position = { 0, 1.1f, 0 };
    cap->rotation = { 90, 0, 0 };
    g3d::Object3D* mound = g->add(g3d::Geometry::sphere(0.9f), matte(mkColor(0x120d18)));
    mound->position = { 0, 0.02f, 0.45f };
    mound->scale = { 0.62f, 0.2f, 0.95f };
}

// banyan: trunk + canopy blobs
void banyan3d(g3d::ScenePtr scene, V3 at, float s) {
    g3d::Object3D* t = scene->add();
    t->position = at;
    t->scale = { s, s, s };
    g3d::Object3D* trunk = t->add(g3d::Geometry::cylinder(0.45f, 5.f, 12), matte(mkColor(0x120b18)));
    trunk->position = { 0, 2.5f, 0 };
    for (int i = 0; i < 6; i++) {
        double a = 2 * PI * i / 6;
        g3d::Object3D* c = t->add(g3d::Geometry::sphere(1.7f - 0.2f * (i % 3)), matte(mkColor(0x0d0813)));
        c->position = { 2.6f * (float)std::cos(a), 5.2f + 0.9f * (float)std::sin(i * 2.1), 2.6f * (float)std::sin(a) };
    }
}

// kampung hut on stilts; if `windowOut` is given it receives the emissive window object
g3d::Object3D* hut3d(g3d::ScenePtr scene, V3 at, float s, float turnDeg, g3d::Object3D** windowOut = nullptr) {
    g3d::Object3D* h = scene->add();
    h->position = at;
    h->rotation = { 0, turnDeg, 0 };
    h->scale = { s, s, s };
    h->add(g3d::Geometry::box(2.6f, 1.5f, 2.2f), matte(mkColor(0x140d20)))->position = { 0, 1.7f, 0 };
    h->add(g3d::Geometry::cone(2.3f, 1.4f, 4), matte(mkColor(0x0d0716)))->position = { 0, 3.15f, 0 };
    for (int sx = -1; sx <= 1; sx += 2)
        for (int sz = -1; sz <= 1; sz += 2)
            h->add(g3d::Geometry::box(0.14f, 0.8f, 0.14f), matte(mkColor(0x0f0a18)))
                ->position = { 0.9f * sx, 0.4f, 0.8f * sz };
    g3d::Object3D* win = h->add(g3d::Geometry::box(0.7f, 0.6f, 0.05f), glow(mkColor(0xffb347), mkColor(0xffb347)));
    win->position = { 0, 1.75f, 1.12f };
    if (windowOut) *windowOut = win;
    return h;
}

// Mbah Séh: robe cone, head, blangkon, staff with an emissive orb
g3d::Object3D* dukun3d(g3d::ScenePtr scene, V3 at, float s) {
    g3d::Object3D* d = scene->add();
    d->position = at;
    d->scale = { s, s, s };
    d->add(g3d::Geometry::cone(0.62f, 1.8f, 16), matte(mkColor(0x2a2050)))->position = { 0, 0.9f, 0 };
    d->add(g3d::Geometry::sphere(0.24f), matte(mkColor(0x2a2050)))->position = { 0, 2.0f, 0 };
    g3d::Object3D* blangkon = d->add(g3d::Geometry::cylinder(0.21f, 0.12f, 16), matte(mkColor(0x1c1436)));
    blangkon->position = { 0, 2.18f, 0 };
    g3d::Object3D* staff = d->add(g3d::Geometry::cylinder(0.035f, 1.9f, 8), matte(mkColor(0x3a2c1a)));
    staff->position = { -0.5f, 0.95f, 0.08f };
    g3d::Object3D* orb = d->add(g3d::Geometry::sphere(0.11f), glow(FLAME, mkColor(0xffb347)));
    orb->position = { -0.5f, 1.95f, 0.08f };
    orb->name = "orb";
    return d;
}

// Demit Wuluhan: hovering horned shadow with burning eyes and flapping wings
g3d::Object3D* demit3d(g3d::ScenePtr scene) {
    g3d::Object3D* root = scene->add();
    g3d::Material body = matte(mkColor(0x180812));
    body.emissive = mkColor(0x300409);
    g3d::Object3D* torso = root->add(g3d::Geometry::sphere(1.0f), body);
    torso->scale = { 0.95f, 1.3f, 0.8f };
    torso->position = { 0, 1.45f, 0 };
    g3d::Material horn = matte(mkColor(0x2a0d12));
    for (int s = -1; s <= 1; s += 2) {
        g3d::Object3D* h = root->add(g3d::Geometry::cone(0.16f, 0.75f, 10), horn);
        h->position = { 0.4f * s, 2.75f, 0 };
        h->rotation = { -12.f, 0, -30.f * s };
    }
    for (int s = -1; s <= 1; s += 2) {
        g3d::Object3D* e = root->add(g3d::Geometry::sphere(0.09f), glow(DEMIT_RED, DEMIT_RED));
        e->position = { 0.32f * s, 1.7f, 0.68f };
        e->name = s < 0 ? "eyeL" : "eyeR";
    }
    g3d::Material wing = matte(mkColor(0x220a14));
    wing.opacity = 0.88f;
    wing.doubleSided = true;
    for (int s = -1; s <= 1; s += 2) {
        g3d::Object3D* wg = root->add();
        wg->position = { 0.45f * s, 2.0f, 0 };
        for (int i = 0; i < 3; i++) {
            g3d::Object3D* m = wg->add(g3d::Geometry::sphere(1.0f), wing);
            m->scale = { 1.05f - 0.18f * i, 0.14f, 0.6f - 0.12f * i };
            m->position = { 0.75f * s * (i + 1) * 0.62f, 0.12f * i, -0.15f * i };
        }
        wg->up = [s](int t, g3d::Object3D& o) { o.rotation.z = s * (14 + 16 * (float)std::sin(t * 0.35)); };
        wg->name = s < 0 ? "wingL" : "wingR";
    }
    return root;
}

// flat ritual circle: two counter-rotating emissive rings + orbiting glyph chips
g3d::Object3D* mandala3d(g3d::ScenePtr scene, V3 at, float r) {
    g3d::Object3D* m = scene->add();
    m->position = at;
    g3d::Material ink = glow(mkColor(0xffd9a0), mkColor(0xcf9a50));
    g3d::Object3D* r1 = m->add(g3d::Geometry::torus(r, 0.03f, 96, 8), ink);
    r1->rotation.x = 90;
    r1->up = [](int t, g3d::Object3D& o) { o.rotation.z = t * 1.2f; };
    g3d::Object3D* r2 = m->add(g3d::Geometry::torus(r * 0.72f, 0.02f, 80, 8), ink);
    r2->rotation.x = 90;
    r2->up = [](int t, g3d::Object3D& o) { o.rotation.z = -t * 1.8f; };
    for (int i = 0; i < 12; i++) {
        g3d::Object3D* chip = m->add(g3d::Geometry::box(0.1f, 0.1f, 0.1f), ink);
        chip->up = [i, r](int t, g3d::Object3D& o) {
            double a = 2 * PI * i / 12 + t * 0.04;
            o.position = { r * 0.86f * (float)std::cos(a), 0.02f, r * 0.86f * (float)std::sin(a) };
        };
    }
    return m;
}

// expanding protective ring-wave (returns the group; the shot animates it)
g3d::Object3D* ringWave(g3d::ScenePtr scene, V3 at, float delay, float life) {
    g3d::Object3D* g = scene->add();
    g->position = at;
    g3d::Material w = glow(mkColor(0xffd9a0), mkColor(0xcf9a50));
    w.opacity = 0;
    g3d::Object3D* ring = g->add(g3d::Geometry::torus(1.f, 0.05f, 64, 8), w);
    ring->rotation.x = 90;
    g->up = [delay, life, ring](int t, g3d::Object3D& o) {
        float u = (t - delay) / life;
        if (u <= 0 || u >= 1) { o.visible = false; return; }
        o.visible = true;
        float k = u * u;
        o.scale = { 1 + 9 * k, 1 + 0.4f * k, 1 + 9 * k };
        ring->material.opacity = 0.8f * (1 - k);
    };
    return g;
}

// candle: wax cylinder + emissive flame
g3d::Object3D* candle3d(g3d::ScenePtr scene, V3 at) {
    g3d::Object3D* c = scene->add();
    c->position = at;
    c->add(g3d::Geometry::cylinder(0.06f, 0.28f, 8), matte(mkColor(0xd8cfc0)))->position = { 0, 0.14f, 0 };
    c->add(g3d::Geometry::sphere(0.05f), glow(FLAME, mkColor(0xffc365)))->position = { 0, 0.34f, 0 };
    return c;
}

// ------------------------------------------------------------------ props department
// dirt mound under a marker
void mound3d(g3d::ScenePtr scene, V3 at, float s) {
    g3d::Object3D* m = scene->add(g3d::Geometry::sphere(0.9f), matte(mkColor(0x141019)));
    m->position = at;
    m->scale = { s, 0.4f * s, 1.35f * s };
}

// sajian offering table: little table, bowls, petals, a burning incense stick
g3d::Object3D* offering3d(g3d::ScenePtr scene, V3 at, float s, float turnDeg = 0) {
    g3d::Object3D* t = scene->add();
    t->position = at;
    t->rotation = { 0, turnDeg, 0 };
    t->scale = { s, s, s };
    t->add(g3d::Geometry::box(1.0f, 0.08f, 0.6f), matte(mkColor(0x2a1c10)))->position = { 0, 0.55f, 0 };
    for (int i = -1; i <= 1; i++)
        t->add(g3d::Geometry::cylinder(0.05f, 0.55f, 8), matte(mkColor(0x241809)))
            ->position = { 0.35f * i, 0.27f, 0 };
    t->add(g3d::Geometry::sphere(0.14f), matte(mkColor(0x3a2a14)))->position = { -0.25f, 0.66f, 0 };
    t->add(g3d::Geometry::sphere(0.14f), matte(mkColor(0x3a2a14)))->position = { 0.25f, 0.66f, 0 };
    for (int i = 0; i < 7; i++) {                       // rose / marigold petals
        g3d::Object3D* p = t->add(g3d::Geometry::sphere(0.035f),
                                  glow(i % 2 ? DEMIT_RED : FLAME, mkColor(i % 2 ? 0x7a1010 : 0x8a5a10)));
        p->position = { (float)rrange(SEED, 700 + i, -0.42f, 0.42f), 0.63f,
                        (float)rrange(SEED, 800 + i, -0.24f, 0.24f) };
    }
    t->add(g3d::Geometry::cylinder(0.012f, 0.5f, 6), matte(mkColor(0x1a120a)))->position = { 0, 0.85f, 0 };
    t->add(g3d::Geometry::sphere(0.03f), glow(FLAME, mkColor(0x9a3a08)))->position = { 0, 1.12f, 0 };
    return t;
}

// bamboo torch: pole, sconce, emissive flame
g3d::Object3D* torch3d(g3d::ScenePtr scene, V3 at, float s) {
    g3d::Object3D* t = scene->add();
    t->position = at;
    t->scale = { s, s, s };
    t->add(g3d::Geometry::cylinder(0.05f, 2.2f, 8), matte(mkColor(0x2a2012)))->position = { 0, 1.1f, 0 };
    t->add(g3d::Geometry::cylinder(0.09f, 0.3f, 8), matte(mkColor(0x1c150c)))->position = { 0, 2.3f, 0 };
    t->add(g3d::Geometry::sphere(0.11f), glow(FLAME, mkColor(0xffc365)))->position = { 0, 2.55f, 0 };
    return t;
}

// split-rail fence segment along local x
void fence3d(g3d::ScenePtr scene, V3 at, float len, int posts, float turnDeg = 0) {
    g3d::Object3D* f = scene->add();
    f->position = at;
    f->rotation = { 0, turnDeg, 0 };
    for (int i = 0; i < posts; i++)
        f->add(g3d::Geometry::box(0.09f, 0.9f, 0.09f), matte(mkColor(0x181019)))
            ->position = { -len / 2 + len * i / (posts - 1.f), 0.45f, 0 };
    for (int r = 0; r < 2; r++)
        f->add(g3d::Geometry::box(len, 0.08f, 0.06f), matte(mkColor(0x1a121a)))
            ->position = { 0, 0.35f + 0.38f * r, 0 };
}

// stone well with a little roof (the village water source, and a hiding place)
void well3d(g3d::ScenePtr scene, V3 at, float s) {
    g3d::Object3D* w = scene->add();
    w->position = at;
    w->scale = { s, s, s };
    g3d::Object3D* ring = w->add(g3d::Geometry::cylinder(0.8f, 0.7f, 20), matte(mkColor(0x232a33)));
    ring->position = { 0, 0.35f, 0 };
    g3d::Object3D* water = w->add(g3d::Geometry::cylinder(0.62f, 0.72f, 20),
                                  glow(mkColor(0x1a2a40), mkColor(0x0a1420)));
    water->position = { 0, 0.36f, 0 };
    for (int sx = -1; sx <= 1; sx += 2)
        w->add(g3d::Geometry::box(0.1f, 1.6f, 0.1f), matte(mkColor(0x181019)))->position = { 0.7f * sx, 1.4f, 0 };
    w->add(g3d::Geometry::cone(1.25f, 0.55f, 4), matte(mkColor(0x0d0716)))->position = { 0, 2.5f, 0 };
}

// lumbung: rice barn on stilts with a thatched pyramid roof
g3d::Object3D* lumbung3d(g3d::ScenePtr scene, V3 at, float s, float turnDeg = 0) {
    g3d::Object3D* b = scene->add();
    b->position = at;
    b->rotation = { 0, turnDeg, 0 };
    b->scale = { s, s, s };
    for (int sx = -1; sx <= 1; sx += 2)
        for (int sz = -1; sz <= 1; sz += 2)
            b->add(g3d::Geometry::box(0.16f, 1.5f, 0.16f), matte(mkColor(0x1c1408)))
                ->position = { 0.9f * sx, 0.75f, 0.7f * sz };
    b->add(g3d::Geometry::box(2.4f, 1.4f, 2.0f), matte(mkColor(0x20160e)))->position = { 0, 2.2f, 0 };
    b->add(g3d::Geometry::cone(2.6f, 1.6f, 4), matte(mkColor(0x2e2410)))->position = { 0, 3.7f, 0 };
    return b;
}

// =================================================================-- the film
void registerComps(Registry& out) {
    Comp c;
    c.name = "dukun-vs-demit-3d";
    c.w = (int)W; c.h = (int)H; c.fps = FPS;
    c.background = NIGHT_TOP;
    c.music = true;
    c.supersample = 1;                     // the GPU pass renders at full res already
    c.assets = [](const Comp&, const Json&) { ensureAudio(); };

    TransitionSeries ts(c.roots, W, H);
    std::vector<int> sceneStart;
    auto sceneShot = [&](int dur, g3d::ScenePtr s3) {
        sceneStart.push_back(ts.end());
        TNode* n = ts.add(dur);
        n->fn = [s3](const Ctx& cx, int) { dr::rect(cx, 0, 0, W, H, NIGHT_TOP); };
        n->add(0, dur)->fn = g3d::draw(s3);
        return n;
    };
    // fade helper for whole shots
    auto fade = [](TNode* n, int dur, int inF = 12, int outF = 16) {
        n->up = [dur, inF, outF](int t, NodeProps& p) {
            p.opacity = (float)interpolate(t, { 0.0, (double)inF, (double)(dur - outF), (double)dur },
                                           { 0, 1, 1, 0 }, clamped());
        };
    };

    // ---- SHOT 1 -- graveyard dolly under the storm (11 s) --------------------
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        for (int i = 0; i < 9; i++)
            grave3d(s3, { -10.f + 2.6f * i + (float)rrange(SEED, i, -0.7f, 0.7f), 0,
                          -2.f + 5.5f * (float)rnd01(SEED, 50 + i) },
                    0.8f + 0.4f * (float)rnd01(SEED, 90 + i), (float)rrange(SEED, 30 + i, -30, 30));
        banyan3d(s3, { 9.f, 0, -6.f }, 1.1f);
        // props: a fence line, an offering left on the cursed grave, a torch by the banyan
        fence3d(s3, { 2.f, 0, -7.5f }, 14, 9);
        offering3d(s3, { -2.5f, 0, 2.9f }, 1.0f, 15);
        torch3d(s3, { 8.2f, 0, -3.6f }, 1.0f);
        // the grave that will break: faint red light already breathing under it
        g3d::Light graveGlow = g3d::Light::point({ -2.5f, 0.15f, 2.0f }, DEMIT_RED, 0.4f, 5);
        graveGlow.up = [](int t, g3d::Light& l) { l.intensity = 0.35f + 0.15f * (float)std::sin(t * 0.11); };
        s3->lights.push_back(graveGlow);
        // moonlight + lightning
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.5f, true));
        g3d::Light bolt = g3d::Light::directional({ 6, 22, 14 }, mkColor(0xcfe0ff), 0);
        bolt.up = [](int t, g3d::Light& l) { l.intensity = 2.4f * flashAt(t, 5); };
        s3->lights.push_back(bolt);
        s3->camera.fov = 42;
        s3->camera.up = [](int t, g3d::Camera& cam) {
            cam.position = { -8 + t * 0.028f, 2.6f - t * 0.0018f, 9.5f - t * 0.008f };
            cam.target = { -4 + t * 0.028f, 0.9f, 0 };
            cam.dof.aperture = 0.8f;
            cam.dof.focusDistance = 11;
        };
        TNode* shot = sceneShot(330, s3);
        fade(shot, 330, 6, 22);
        shot->add(0, 330)->fn = [](const Ctx& cx, int t) {
            rain(cx, t, std::min(1.f, t / 50.f));
            actCard(cx, "BABAK I", "YANG BANGUN", capA(t, 60, 90, 200, 230));
            float a1 = capA(t, 26, 44, 140, 165);
            tracked(cx, "KAMPUNG WANARA - 1974", W / 2, H * 0.74f, 30, 12, BONE, a1, 1);
            float a2 = capA(t, 210, 232, 296, 318);
            caption(cx, "Hujan turun malam ini. Tetapi ia tidak turun sendirian.", H * 0.78f, a2);
        };
    }

    // ---- SHOT 2 -- the demit rises from the grave (11 s) ----------------------
    ts.transition(Transition::fade(TR));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        grave3d(s3, { 0, 0, 0 }, 1.8f, 0);
        grave3d(s3, { -3.4f, 0, 1.2f }, 1.1f, 20);
        grave3d(s3, { 3.1f, 0, 0.8f }, 1.0f, -15);
        offering3d(s3, { 1.6f, 0, 1.6f }, 1.0f, -20);
        banyan3d(s3, { 6.5f, 0, -5.f }, 1.0f);
        g3d::Object3D* demit = demit3d(s3);
        demit->up = [](int t, g3d::Object3D& o) {
            float rise = (float)interpolate(t, { 60.0, 220.0 }, { -2.6, 0.0 }, clamped(ease::out(ease::cubic)));
            o.position = { 0, rise, 0 };
            o.rotation.y = (float)std::sin(t * 0.05) * 6;
            float k = 0.55f + 0.35f * (rise + 2.6f) / 2.6f;
            o.scale = { k, k, k };
        };
        g3d::Light graveGlow = g3d::Light::point({ 0, 0.1f, 0.6f }, DEMIT_RED, 0.3f, 7);
        graveGlow.up = [](int t, g3d::Light& l) {
            l.intensity = (float)interpolate(t, { 40.0, 240.0 }, { 0.4, 1.25 }, clamped());
        };
        s3->lights.push_back(graveGlow);
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.45f, true));
        g3d::Light bolt = g3d::Light::directional({ 6, 22, 14 }, mkColor(0xcfe0ff), 0);
        bolt.up = [](int t, g3d::Light& l) { l.intensity = 2.2f * flashAt(t, 9); };
        s3->lights.push_back(bolt);
        s3->camera.fov = 44;
        s3->camera.up = [](int t, g3d::Camera& cam) {
            cam.position = { 0.4f * (float)std::sin(t * 0.01), 0.85f, 8.4f - t * 0.004f };
            cam.target = { 0, 0.7f + 1.1f * (float)interpolate(t, { 80.0, 260.0 }, { 0.0, 1.0 }, clamped()), 0 };
            cam.dof.aperture = 1.1f;
            cam.dof.focusDistance = 7.5f;
        };
        TNode* shot = sceneShot(330, s3);
        fade(shot, 330);
        shot->add(0, 330)->fn = [](const Ctx& cx, int t) {
            rain(cx, t, 1);
            float a = capA(t, 300, 318, 372, 392);
            caption(cx, "Yang dikubur bertahun-tahun... mulai ingat jalan pulang.", H * 0.78f, a, 42);
        };
    }

    // ---- SHOT 3 -- title sequence (9 s) ---------------------------------------
    ts.transition(Transition::fade(TR));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        banyan3d(s3, { -4.f, 0, -3.f }, 1.15f);
        grave3d(s3, { 3.5f, 0, 0.5f }, 1.2f, 10);
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.5f, true));
        s3->camera.up = [](int t, g3d::Camera& cam) {
            double a = 0.55 + t * 0.0011;
            cam.position = { 8.f * (float)std::cos(a), 1.6f, 8.f * (float)std::sin(a) };
            cam.target = { 0, 1.8f, 0 };
            cam.dof.aperture = 0.9f;
            cam.dof.focusDistance = 8;
        };
        TNode* shot = sceneShot(270, s3);
        fade(shot, 270, 8, 20);
        TNode* over = shot->add(0, 270);
        over->fn = [](const Ctx& cx, int t) {
            rain(cx, t, 0.5f);
            float a = (float)interpolate(t, { 8.0, 26.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
            // the title breathes in: wide tracking settling into place
            float track = (float)interpolate(t, { 10.0, 80.0 }, { 30.0, 9.0 }, clamped(ease::out(ease::cubic)));
            tracked(cx, "DUKUN", W / 2, H * 0.28f, 170, track * 1.4f, BONE, a, 1);
            rule(cx, W / 2, H * 0.28f + 196, 210 * a, a);
            tracked(cx, "vs  DEMIT", W / 2, H * 0.28f + 216, 74, track, DEMIT_RED, a, 1);
            tracked(cx, "EDISI TIGA DIMENSI", W / 2, H * 0.565f, 30, 12, mkColor(0xcf9a50), a, 1);
            tracked(cx, "setiap piksel dan nada dibuat oleh kode", W / 2, H * 0.565f + 46, 27, 4,
                    mkColor(0xb8a8d8), a * 0.9f, 2);
        };
    }

    // ---- SHOT 4 -- the village pan (12 s) --------------------------------------
    ts.transition(Transition::slide(TR, Direction::FromRight));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        g3d::Object3D* sickWindow = nullptr;
        hut3d(s3, { 0.f, 0, 0 }, 1.15f, 0, &sickWindow);
        hut3d(s3, { -9.f, 0, -1.5f }, 1.0f, 8);
        hut3d(s3, { 9.5f, 0, -1.f }, 1.05f, -6);
        lumbung3d(s3, { -14.f, 0, -4.f }, 1.05f, 12);
        fence3d(s3, { 0.f, 0, -7.5f }, 26, 15);
        torch3d(s3, { -2.6f, 0, 3.1f }, 1.0f);
        torch3d(s3, { 2.6f, 0, 3.1f }, 1.0f);
        well3d(s3, { 13.f, 0, 3.5f }, 1.0f);
        // window flicker on the sick hut
        g3d::Object3D* flickerHost = s3->add();
        flickerHost->up = [sickWindow](int t, g3d::Object3D&) {
            if (sickWindow) sickWindow->material.emissive =
                withAlpha(mkColor(0xffb347), 0.7f + 0.3f * (float)std::sin(t * 1.7));
        };
        // villagers with torches
        for (int i = 0; i < 4; i++) {
            g3d::Object3D* v = s3->add();
            v->add(g3d::Geometry::cylinder(0.16f, 0.85f, 10), matte(mkColor(0x0c0816)))->position = { 0, 0.42f, 0 };
            v->add(g3d::Geometry::sphere(0.14f), matte(mkColor(0x0c0816)))->position = { 0, 1.0f, 0 };
            v->add(g3d::Geometry::sphere(0.07f), glow(FLAME, mkColor(0xffc365)))->position = { 0.22f, 1.05f, 0 };
            v->up = [i](int t, g3d::Object3D& o) {
                float u = (float)std::fmod(t * 0.035 + i * 0.31f, 1.3f) - 0.15f;
                o.position = { -11 + u * 22, 0, 2.6f + 0.5f * (float)std::sin(i * 2.1) };
            };
        }
        // the demit glides overhead, late
        g3d::Object3D* demit = demit3d(s3);
        demit->scale = { 0.7f, 0.7f, 0.7f };
        demit->up = [](int t, g3d::Object3D& o) {
            float fly = (float)interpolate(t, { 250.0, 360.0 }, { -14.0, 14.0 }, clamped(ease::inOut(ease::sine)));
            o.position = { fly, 5.4f - 0.6f * (float)std::sin(t * 0.1), -3.f };
        };
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.45f, true));
        s3->lights.push_back(g3d::Light::point({ 0, 1.9f, 1.4f }, mkColor(0xffb347), 1.5f, 7));
        s3->camera.fov = 40;
        s3->camera.up = [](int t, g3d::Camera& cam) {
            cam.position = { -8 + t * 0.026f, 2.4f, 11.f };
            cam.target = { -6 + t * 0.026f, 1.6f, 0 };
            cam.dof.aperture = 0.7f;
            cam.dof.focusDistance = 11.5f;
        };
        TNode* shot = sceneShot(360, s3);
        fade(shot, 360);
        shot->add(0, 360)->fn = [](const Ctx& cx, int t) {
            rain(cx, t, 0.4f);
            actCard(cx, "BABAK II", "YANG DIPANGGIL", capA(t, 60, 90, 200, 230));
            float a1 = capA(t, 26, 46, 150, 175);
            caption(cx, "Anak pertama demam pada Senin. Yang kedua, pada Kamis.", H * 0.74f, a1);
            float a2 = capA(t, 250, 270, 330, 352);
            caption(cx, "Malam ini, giliran anak ketiga.", H * 0.74f, a2);
        };
    }

    // ---- SHOT 5 -- the ritual (14 s) -------------------------------------------
    ts.transition(Transition::wipe(TR, Direction::FromLeft));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        dukun3d(s3, { 0, 0, 0 }, 1.15f);
        for (int i = 0; i < 12; i++) {
            double th = 2 * PI * i / 12;
            candle3d(s3, { 3.2f * (float)std::cos(th), 0, 3.2f * (float)std::sin(th) });
        }
        mandala3d(s3, { 0, 0.02f, 0 }, 2.1f);
        offering3d(s3, { 1.7f, 0, 1.7f }, 1.0f, -30);
        torch3d(s3, { -3.6f, 0, -3.4f }, 1.05f);
        torch3d(s3, { 3.8f, 0, -3.2f }, 1.05f);
        for (int i = 0; i < 3; i++)
            s3->add(g3d::Geometry::cylinder(0.12f, 0.4f, 10), matte(mkColor(0x0c0816)))
                ->position = { 2.4f * (float)std::cos(1.2 + i * 0.8), 0.2f, 3.6f + (float)std::sin(i) };
        g3d::Light candleLight = g3d::Light::point({ 0, 1.1f, 0 }, mkColor(0xffb347), 1.6f, 6.5f);
        candleLight.castShadow = true;
        candleLight.up = [](int t, g3d::Light& l) {
            l.intensity = 1.5f + 0.25f * (float)std::sin(t * 0.9) * (float)std::sin(t * 0.23);
        };
        s3->lights.push_back(candleLight);
        s3->lights.push_back(g3d::Light::point({ 0.1f, 2.6f, -3.3f }, mkColor(0xffc365), 0.7f, 6));
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.35f, false));
        s3->camera.fov = 42;
        s3->camera.up = [](int t, g3d::Camera& cam) {
            double a = 0.9 + t * 0.0022;
            float d = 6.8f - 0.8f * (float)interpolate(t, { 0, 420 }, { 0, 1 });
            cam.position = { d * (float)std::cos(a), 2.3f - 0.5f * (float)interpolate(t, { 0, 420 }, { 0, 1 }), d * (float)std::sin(a) };
            cam.target = { 0, 1.1f, 0 };
            cam.dof.aperture = 0.8f;
            cam.dof.focusDistance = d;
        };
        TNode* shot = sceneShot(420, s3);
        fade(shot, 420);
        shot->add(0, 420)->fn = [](const Ctx& cx, int t) {
            fog2d(cx, t, H * 0.9f, 31, 0.05f);
            rain(cx, t, (float)interpolate(t, { 300.0, 400.0 }, { 0.0, 0.8f }, clamped()));
            float a1 = capA(t, 20, 40, 150, 180);
            caption(cx, "\"Huuuu... angker mulang... kula dhawuhi...\"", H * 0.74f, a1);
            float a2 = capA(t, 190, 210, 330, 360);
            caption(cx, "\"Demi asma tertinggi, kembalilah ke tanahmu!\"", H * 0.74f, a2);
            float a3 = capA(t, 370, 390, 396, 414);
            caption(cx, "Kemenyan mengepul. Malam menahan napas.", H * 0.74f, a3);
        };
    }

    // ---- SHOT 6 -- the duel (18 s) ----------------------------------------------
    ts.transition(Transition::fade(TR));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        dukun3d(s3, { -3.2f, 0, 0 }, 1.25f);
        fence3d(s3, { 0.f, 0, -9.f }, 30, 17);
        torch3d(s3, { -1.2f, 0, -5.5f }, 1.1f);
        torch3d(s3, { 1.6f, 0, -5.5f }, 1.1f);
        g3d::Object3D* demit = demit3d(s3);
        demit->up = [](int t, g3d::Object3D& o) {
            double a = t * 0.045;
            V3 p{ 3.4f + 1.6f * (float)std::cos(a), 1.9f + 0.7f * (float)std::sin(a), 1.2f * (float)std::sin(a) };
            for (double l : { 195.0, 295.0, 395.0 }) {          // lunges toward the dukun
                double d = t - l;
                if (d > 0 && d < 35) {
                    float k = (float)std::sin(d / 35 * PI);
                    p.x -= 2.6f * k;
                    p.y -= 0.4f * k;
                }
            }
            if (t > 450) {                                       // recoils from the beam
                float r = (float)interpolate(t, { 450.0, 540.0 }, { 0.0, 1.0 }, clamped());
                p.x += 2.2f * r;
                p.y += 0.8f * r;
            }
            o.position = p;
            o.rotation.y = -90 + 40 * (float)std::sin(t * 0.05);
        };
        ringWave(s3, { -3.2f, 0.06f, 0 }, 100, 70);
        ringWave(s3, { -3.2f, 0.06f, 0 }, 160, 70);
        ringWave(s3, { -3.2f, 0.06f, 0 }, 220, 70);
        // the banishing beam, planted late
        g3d::Object3D* beam = s3->add(g3d::Geometry::cylinder(0.5f, 26.f, 16),
                                      glow(mkColor(0xfff2d8), mkColor(0xfff2d8)));
        beam->position = { -3.2f, 13.f, 0 };
        beam->up = [](int t, g3d::Object3D& o) {
            float b = (float)interpolate(t, { 430.0, 470.0, 530.0, 540.0 }, { 0.0, 1.0, 1.0, 0.0 }, clamped());
            o.visible = b > 0.01f;
            o.material.opacity = 0.55f * b;
            o.scale = { b, 1, b };
        };
        g3d::Light redLight = g3d::Light::point({ 3.4f, 2.2f, 0 }, DEMIT_RED, 1.8f, 12);
        redLight.up = [](int t, g3d::Light& l) {
            l.position = { 3.4f + 1.6f * (float)std::cos(t * 0.045), 2.2f + 0.7f * (float)std::sin(t * 0.045), 1.2f * (float)std::sin(t * 0.045) };
            if (t > 450) l.intensity = 1.8f * (1 - (float)interpolate(t, { 450.0, 540.0 }, { 0.0, 1.0 }, clamped()));
        };
        s3->lights.push_back(redLight);
        s3->lights.push_back(g3d::Light::point({ -3.2f, 1.4f, 0.3f }, mkColor(0xffb347), 1.2f, 8));
        g3d::Light beamLight = g3d::Light::point({ -3.2f, 2.f, 0.2f }, mkColor(0xfff2d8), 0);
        beamLight.up = [](int t, g3d::Light& l) {
            l.intensity = 3.f * (float)interpolate(t, { 430.0, 470.0, 530.0, 540.0 }, { 0.0, 1.0, 1.0, 0.0 }, clamped());
        };
        s3->lights.push_back(beamLight);
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.4f, true));
        s3->camera.fov = 44;
        s3->camera.up = [](int t, g3d::Camera& cam) {
            float shake = 0;
            if (t > 160 && t < 430) shake = 0.10f;
            if (t > 430 && t < 540) shake = 0.16f;
            cam.position = { 0.2f + (float)rrange(SEED, (unsigned long long)t * 13 + 1, -shake, shake),
                             2.0f + (float)rrange(SEED, (unsigned long long)t * 13 + 2, -shake, shake), 9.5f };
            cam.target = { 0.2f, 1.6f, 0 };
            cam.dof.aperture = 0.7f;
            cam.dof.focusDistance = 9.5f;
        };
        TNode* shot = sceneShot(540, s3);
        fade(shot, 540);
        shot->add(0, 540)->fn = [](const Ctx& cx, int t) {
            rain(cx, t, 0.8f);
            actCard(cx, "BABAK III", "YANG DIKUBURKAN", capA(t, 40, 70, 170, 200));
            float a = capA(t, 200, 225, 320, 350);
            caption(cx, "\"Asma Bismillah! Kembalilah ke alam gaib, demit!\"", H * 0.74f, a, 42);
            // the beam flash
            float boom = (float)interpolate(t, { 440.0, 448.0, 462.0, 472.0 }, { 0, 1, 1, 0 }, clamped());
            if (boom > 0) dr::rect(cx, -50, -50, W + 100, H + 100, withAlpha(mkColor(0xfff2d8), 0.5f * boom));
        };
    }

    // ---- SHOT 7 -- the banishment vortex (12 s) ----------------------------------
    ts.transition(Transition::fade(TR));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        grave3d(s3, { 0, 0, 0 }, 1.8f, 0);
        dukun3d(s3, { -4.5f, 0, 0.5f }, 1.25f);
        fence3d(s3, { -2.f, 0, -8.f }, 22, 13);
        offering3d(s3, { 1.9f, 0, 1.9f }, 1.0f, 40);
        g3d::Object3D* demit = demit3d(s3);
        demit->up = [](int t, g3d::Object3D& o) {
            float suck = (float)interpolate(t, { 30.0, 300.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::cubic)));
            o.position = { 0, 1.9f * (1 - suck) - 1.6f * suck, 0 };
            float k = 1.15f * (1 - 0.7f * suck);
            o.scale = { k, k, k };
            o.rotation.y = t * 2.2f * suck;
        };
        for (int i = 0; i < 26; i++) {
            g3d::Object3D* p = s3->add(g3d::Geometry::sphere(0.05f), glow(DEMIT_RED, mkColor(0x8a1010)));
            p->up = [i](int t, g3d::Object3D& o) {
                float u = std::fmod(t * 0.014f + i / 26.f, 1.f);
                double a = u * 10 + i;
                float r = (1 - u) * 4.2f;
                o.position = { r * (float)std::cos(a), 0.1f + (1 - u) * 2.6f, r * (float)std::sin(a) };
            };
        }
        g3d::Light redLight = g3d::Light::point({ 0, 1.2f, 0 }, DEMIT_RED, 2.2f, 12);
        redLight.up = [](int t, g3d::Light& l) {
            l.intensity = 2.2f * (1 - (float)interpolate(t, { 60.0, 320.0 }, { 0.0, 1.0 }, clamped()));
        };
        s3->lights.push_back(redLight);
        s3->lights.push_back(g3d::Light::point({ -4.5f, 1.5f, 0.8f }, mkColor(0xffb347), 1.1f, 7));
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.4f, true));
        s3->camera.up = [](int t, g3d::Camera& cam) {
            double a = 1.4 + t * 0.0012;
            cam.position = { 6.f * (float)std::cos(a), 1.9f, 6.f * (float)std::sin(a) };
            cam.target = { 0, 1.0f, 0 };
            cam.dof.aperture = 0.9f;
            cam.dof.focusDistance = 6;
        };
        TNode* shot = sceneShot(360, s3);
        fade(shot, 360);
        shot->add(0, 360)->fn = [](const Ctx& cx, int t) {
            rain(cx, t, (float)interpolate(t, { 200.0, 340.0 }, { 0.6f, 0.0 }, clamped()));
            float a = capA(t, 60, 84, 300, 330);
            caption(cx, "Yang dari tanah, kepada tanah dikembalikan.", H * 0.74f, a);
        };
    }

    // ---- SHOT 8 -- dawn... and the twist (12 s) -----------------------------------
    ts.transition(Transition::wipe(TR, Direction::FromTop));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        grave3d(s3, { -1.5f, 0, 0.5f }, 1.5f, 0);
        grave3d(s3, { 1.8f, 0, -0.4f }, 1.0f, 15);
        banyan3d(s3, { 7.f, 0, -6.f }, 1.1f);
        well3d(s3, { 4.8f, 0, 3.4f }, 1.0f);
        lumbung3d(s3, { -8.5f, 0, -4.f }, 1.0f, -10);
        fence3d(s3, { 0.f, 0, -8.f }, 20, 12);
        g3d::Object3D* dukun = dukun3d(s3, { 5.5f, 0, 2.5f }, 1.1f);
        dukun->rotation.y = -35;
        // the twist: eyes re-open in the grave, very late
        std::vector<g3d::Object3D*> eyes;
        for (int s = -1; s <= 1; s += 2) {
            g3d::Object3D* e = s3->add(g3d::Geometry::sphere(0.06f), glow(DEMIT_RED, DEMIT_RED));
            e->position = { -1.5f + 0.14f * s, 0.9f, 0.62f };
            e->up = [](int t, g3d::Object3D& o) {
                float k = (float)interpolate(t, { 280.0, 315.0 }, { 0.0, 1.0 }, clamped(ease::out(ease::cubic)));
                o.scale = { k, k, k };
                o.visible = k > 0.02f;
            };
            eyes.push_back(e);
        }
        (void)eyes;
        g3d::Light sun = g3d::Light::directional({ 30, -6, 20 }, mkColor(0xffb347), 0, false);
        sun.up = [](int t, g3d::Light& l) {
            float dawn = (float)interpolate(t, { 20.0, 200.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::sine)));
            l.position = { 30, -6 + 26 * dawn, 20 };
            l.intensity = 1.5f * dawn;
        };
        s3->lights.push_back(sun);
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.4f, true));
        s3->up = [](int t, g3d::Scene& sc) {
            float dawn = (float)interpolate(t, { 20.0, 200.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::sine)));
            sc.ambient = 0.22f + 0.3f * dawn;
            sc.fogColor = mixC(FOG_COL, mkColor(0x8a5a48), dawn);
            sc.skyColor = mixC(mkColor(0x101a30), mkColor(0xffb347), dawn);
        };
        s3->camera.up = [](int t, g3d::Camera& cam) {
            float d = 7.5f + 2.5f * (float)interpolate(t, { 0, 360 }, { 0, 1 }, clamped(ease::inOut(ease::sine)));
            cam.position = { -1.f, 2.2f + 1.2f * (float)interpolate(t, { 0, 360 }, { 0, 1 }), d };
            cam.target = { -0.4f, 0.8f, 0 };
            cam.dof.aperture = 0.7f;
            cam.dof.focusDistance = d;
        };
        TNode* shot = sceneShot(360, s3);
        fade(shot, 360, 4, 18);
        shot->add(0, 360)->fn = [](const Ctx& cx, int t) {
            float dawn = (float)interpolate(t, { 20.0, 200.0 }, { 0.0, 1.0 }, clamped(ease::inOut(ease::sine)));
            // redo the backdrop so sky and light agree (drawn under the 3D already, this
            // paints a soft haze that lifts as the sun rises)
            dr::rect(cx, 0, 0, W, H, withAlpha(mkColor(0xffb347), 0.10f * dawn));
            actCard(cx, "EPILOG", "FAJAR", capA(t, 30, 60, 170, 200));
            float a = capA(t, 200, 222, 300, 330);
            caption(cx, "Anak itu bangun, dan minta air.", H * 0.74f, a);
            float a2 = capA(t, 310, 332, 358, 376);
            caption(cx, "Tetapi tanah pun ingatan.", H * 0.74f, a2, 44);
        };
    }

    // ---- SHOT 9 -- credits (10 s) ---------------------------------------------------
    ts.transition(Transition::fade(TR));
    {
        auto s3 = std::make_shared<g3d::Scene>();
        nightWorld(s3);
        grave3d(s3, { -2.f, 0, 0 }, 1.2f, 0);
        banyan3d(s3, { 5.f, 0, -5.f }, 1.2f);
        s3->lights.push_back(g3d::Light::directional({ 30, 18, 20 }, mkColor(0xffc37a), 0.9f, true));
        s3->lights.push_back(g3d::Light::directional({ 18, 26, -20 }, mkColor(0x9aa4d8), 0.3f, false));
        s3->up = [](int, g3d::Scene& sc) { sc.ambient = 0.4f; };
        s3->camera.up = [](int t, g3d::Camera& cam) {
            double a = 0.8 + t * 0.0008;
            cam.position = { 7.f * (float)std::cos(a), 2.0f, 7.f * (float)std::sin(a) };
            cam.target = { 0, 1.0f, 0 };
        };
        TNode* shot = sceneShot(300, s3);
        fade(shot, 300, 4, 22);
        TNode* over = shot->add(0, 300);
        over->fn = [](const Ctx& cx, int t) {
            TextStyle tamat;
            tamat.font = serif(1); tamat.size = 120; tamat.align = Align::Center;
            tamat.color = withAlpha(BONE, (float)interpolate(t, { 15.0, 40.0 }, { 0.0, 1.0 }, clamped()));
            dr::textBox(cx, "TAMAT", { 200, H * 0.30f, W - 400, 150 }, tamat);
            TextStyle cred;
            cred.font = serif(0); cred.size = 30; cred.align = Align::Center;
            float roll = (float)interpolate(t, { 50.0, 285.0 }, { 0.0, 1.0 }, clamped(ease::linear));
            auto line = [&](const char* role, const char* name, double at) {
                float a = (float)interpolate(roll, { at, at + 0.08, at + 0.17, at + 0.25 }, { 0, 1, 1, 0 }, clamped());
                if (a <= 0.01f) return;
                cred.color = withAlpha(mkColor(0xcabfe0), a * 0.75f);
                dr::textBox(cx, role, { 200, H * 0.5f - 34 * (1 - a), W - 400, 40 }, cred);
                cred.color = withAlpha(BONE, a);
                dr::textBox(cx, name, { 200, H * 0.5f + 8 - 34 * (1 - a), W - 400, 40 }, cred);
            };
            line("SUTRADARA", "g3d::Scene + GL", 0.02);
            line("SKENARIO", "storyboard.cpp", 0.27);
            line("MUSIK & SUARA", "rmtn::synth + writeWavMono", 0.52);
            line("PAMAIN", "Mbah S\xC3\xA9h, Demit Wuluhan, warga Kampung Wanara", 0.77);
        };
    }

    // grain + letterbox over everything
    TNode* overlay = addRoot(c.roots, 0, ts.end());
    overlay->fn = [](const Ctx& cx, int t) { grainVignette(cx, t); };

    c.duration = ts.end();

    // ---------------------------------------------------------------- audio
    int stormEnd = sceneStart[6] + 200;
    AudioClip& wind = media::audio(addRoot(c.roots, 0, c.duration), AUDIO_DIR + "/wind.wav");
    wind.loop = true; wind.volume = 0.9f;
    wind.volumeAt = [end = c.duration](int t) {
        return (float)interpolate(t, { 0.0, 90.0, (double)end - 400, (double)end }, { 0.0, 1.0, 1.0, 0.0 }, clamped());
    };
    AudioClip& rainClip = media::audio(addRoot(c.roots, 0, stormEnd), AUDIO_DIR + "/rain.wav");
    rainClip.loop = true; rainClip.volume = 1.0f;
    rainClip.volumeAt = [stormEnd](int t) {
        return 0.75f * (float)interpolate(t, { 0.0, 120.0, (double)stormEnd - 150, (double)stormEnd },
                                          { 0.0, 1.0, 1.0, 0.0 }, clamped());
    };
    std::vector<int> screeches{ sceneStart[1] + 230, sceneStart[3] + 260, sceneStart[5] + 195,
                                sceneStart[5] + 295, sceneStart[5] + 395, sceneStart[5] + 435,
                                sceneStart[6] + 100 };
    for (int f : screeches) {
        if (f + 48 >= c.duration) continue;
        AudioClip& sc = media::audio(addRoot(c.roots, f, 48), AUDIO_DIR + "/screech.wav");
        sc.volume = 0.55f;
    }

    // ---------------------------------------------------------------- score
    Song& s = c.song;
    std::vector<double> sec;
    for (int f : sceneStart) sec.push_back((double)f / FPS);
    double endSec = (double)c.duration / FPS;

    for (double t = 0; t < endSec - 1; t += 3.9)
        s.push_back({ t, 4.2, ((long long)(t / 3.9) % 2) ? 77.78 : 55.0, 0.12, false });
    for (size_t i = 1; i < sec.size(); i++)
        for (int k = 0; k < 3; k++)
            s.push_back({ sec[i] + k * 0.04, 0.5, 587.33 * (1 + 0.07 * k), 0.08, true });
    for (double off : { 0.4, 4.3, 8.9, 26.0, 33.5 })
        s.push_back({ sec[0] + off, 1.1, 40.0, 0.45, true });
    double minor[6] = { 220.0, 246.94, 261.63, 293.66, 329.63, 392.0 };
    for (int i = 0; i < 34; i++)
        s.push_back({ sec[0] + 1.2 + i * 1.31, 1.1, minor[(i * 7 / 3) % 6] * (i % 3 ? 1 : 0.5), 0.07, true });
    for (int i = 0; i < 12; i++) {
        double f[5] = { 196.0, 220.0, 233.08, 261.63, 146.83 };
        s.push_back({ sec[4] + 0.5 + i * 1.05, 0.9, f[i % 5], 0.11, true });
        s.push_back({ sec[4] + 0.5 + i * 1.05, 0.28, 68.0, 0.30, true });
    }
    double t0 = sec[5], t1 = sec[7] + 12;
    for (double t = t0; t < t1; t += 0.72) {
        s.push_back({ t, 0.20, 50.0, 0.40, true });
        s.push_back({ t + 0.22, 0.16, 46.0, 0.28, true });
    }
    for (double off : { 6.5, 9.5, 13.2, 18.0, 19.6 })
        s.push_back({ sec[5] + off, 0.35, 40.0, 0.5, true });
    s.push_back({ sec[5] + 14.4, 4.0, 65.41, 0.30, false });
    s.push_back({ sec[5] + 14.4, 4.0, 130.81, 0.18, false });
    s.push_back({ sec[7] + 0.8, 5.5, 220.0, 0.12, false });
    s.push_back({ sec[7] + 0.8, 5.5, 277.18, 0.09, false });
    s.push_back({ sec[7] + 0.8, 5.5, 329.63, 0.07, false });
    s.push_back({ sec[8] + 9.8, 0.7, 43.65, 0.5, true });
    for (int i = 0; i < 10; i++)
        s.push_back({ sec[8] + 1.0 + i * 0.62, 0.9, minor[(i * 5 / 2) % 6] * 2, 0.08, true });

    out.push_back(std::move(c));
}

} // namespace

int main(int argc, const char** argv) { return runCli(argc, argv, registerComps); }
